import pyomo.environ as pyo

DATA = {
    "foods": ["Bread", "Milk", "Fish", "Potato"],
    "nutrients": ["protein", "carbs", "calories"],
    "cost": {
        "Bread": 3,
        "Milk": 4,
        "Fish": 8,
        "Potato": 2,
    },
    "protein": {
        "Bread": 4,
        "Milk": 6,
        "Fish": 20,
        "Potato": 1,
    },
    "carbs": {
        "Bread": 7,
        "Milk": 10,
        "Fish": 0,
        "Potato": 30,
    },
    "calories": {
        "Bread": 130,
        "Milk": 120,
        "Fish": 150,
        "Potato": 70,
    },
    "requirement": {
        "protein": 40,
        "carbs": 50,
        "calories": 450,
    },
    # maps nutrient name -> content dict
    "content": {
        "protein": {"Bread": 4, "Milk": 6, "Fish": 20, "Potato": 1},
        "carbs": {"Bread": 7, "Milk": 10, "Fish": 0, "Potato": 30},
        "calories": {"Bread": 130, "Milk": 120, "Fish": 150, "Potato": 70},
    },
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.I = pyo.Set(initialize=d["foods"])
    model.N = pyo.Set(initialize=d["nutrients"])

    # x[i] = servings of food i to purchase
    model.x = pyo.Var(model.I, domain=pyo.NonNegativeReals, bounds=(0, None))

    # Objective: minimise total cost
    def obj_rule(m):
        return sum(d["cost"][i] * m.x[i] for i in m.I)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # One constraint per nutrient: intake must meet requirement
    def nutrient_rule(m, n):
        return sum(d["content"][n][i] * m.x[i] for i in m.I) >= d["requirement"][n]

    model.nutrient_req = pyo.Constraint(model.N, rule=nutrient_rule)

    return model
